#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# ghcr 이미지 배포로 옮기기 전에 사람이 해야 하는 일(2026-09-17 설계).
# 이 개발 머신(sub2)에서 돌린다 — gh CLI 와 `ssh sub`, sub 를 거친 `ssh oracle` 을 쓴다.
# mac 에서 할 일은 명령을 보여주고, 끝나면 GitHub API 로 러너가 붙었는지 확인한다.

cd "$(dirname "$0")/.."   # set_secret 이 저장소를 현재 디렉터리에서 고른다
REPO="sandcorporation/laurio"
STAGING_ENV="/server/jenkins/workspace/laurio/docker/.env.staging"   # sub 호스트
PROD_ENV="/var/jenkins_home/workspace/codemit/docker/.env.prod"       # oracle 호스트
# 다시 돌릴 때의 기본값 — 저장소 밖에 둔다(비밀값이 섞인다).
ENV_FILE="${HOME}/.config/codemit-ghcr-wizard.env"
mkdir -p "$(dirname "$ENV_FILE")"; touch "$ENV_FILE"; chmod 600 "$ENV_FILE"

_ssh_noise='post-quantum|store now|upgraded'
# on_sub / on_oracle: 표준입력의 bash 스크립트를 그 호스트에서 돈다. 값은 명령줄이
# 아니라 스크립트 본문(표준입력)으로 넘어가 ps 에 드러나지 않는다.
on_sub()    { ssh sub 'bash -s' 2> >(grep -vE "$_ssh_noise" >&2); }
on_oracle() { ssh sub 'timeout 120 ssh -o BatchMode=yes oracle "bash -s"' 2> >(grep -vE "$_ssh_noise" >&2); }

# upsert_remote_script FILE KEY VALUE — 원격에서 돌릴 upsert 조각(sudo).
# 파일을 옮기지 않고 제자리에 덮어쓴다 — oracle 은 SELinux 라 /tmp 에서 mv 한
# 파일은 라벨이 바뀌어 컨테이너가 못 읽을 수 있고, 소유자·권한도 그대로 남는다.
upsert_remote_script() {
  printf 'f=%q; k=%q; v=%q\n' "$1" "$2" "$3"
  cat <<'EOS'
tmp=$(sudo mktemp)
sudo sh -c "grep -vE '^${k}=' '$f' > '$tmp' || true"
printf '%s=%s\n' "$k" "$v" | sudo tee -a "$tmp" >/dev/null
sudo sh -c "cat '$tmp' > '$f'"; sudo rm -f "$tmp"
EOS
}

# set_repo_var NAME VALUE — 저장소 변수(비밀 아님). environment 기능은 free 조직의
# 비공개 저장소에서 쓸 수 없어 접두어(STAGING_/PROD_)로 환경을 가른다.
set_repo_var() {
  if gh variable set "$1" --repo "$REPO" --body "$2" >/dev/null 2>&1; then
    printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$1"
  else
    SKIPPED+=("GitHub variable $1"); warn "GitHub variable $1 을 설정하지 못했다"
  fi
}

TOTAL_STAGES=7

banner "Codemit — ghcr 이미지 배포 준비 (사람 작업)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "사전 확인"
say "gh 권한과 두 서버 접속, env 파일 둘을 확인합니다."
gh auth status >/dev/null 2>&1 || { warn "gh 로그인이 필요합니다: gh auth login"; exit 1; }
[[ "$(gh api "repos/$REPO" --jq .permissions.admin)" == "true" ]] || { warn "$REPO 관리자 권한이 필요합니다"; exit 1; }
printf 'sudo -n test -f %q && stat -c "%%a" %q\n' "$STAGING_ENV" "$STAGING_ENV" | on_sub | sed 's/^/  sub   .env.staging 권한: /' \
  || { warn "sub 에 접속하지 못했거나 $STAGING_ENV 가 없습니다(sudo 필요)"; exit 1; }
printf 'sudo -n test -f %q && sudo -n stat -c "%%a" %q\n' "$PROD_ENV" "$PROD_ENV" | on_oracle | sed 's/^/  oracle .env.prod 권한: /' \
  || { warn "oracle 에 접속하지 못했거나 $PROD_ENV 가 없습니다(sudo 필요)"; exit 1; }
warn ".env.staging 은 비밀값 파일인데 누구나 읽을 수 있는(644) 상태였습니다(2026-09-17 확인)."
if confirm "sub 의 .env.staging 권한을 600 으로 바꿀까요? (Jenkins 는 root 로 돌아 영향 없음)"; then
  printf 'sudo chmod 600 %q && stat -c "  → %%a" %q\n' "$STAGING_ENV" "$STAGING_ENV" | on_sub
fi
pause "계속하려면 Enter"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "mac: Docker Desktop 상시 가동"
say "arm64(prod) 이미지는 mac 에서 굽습니다. mac 이 잠들면 prod 승격이 기다립니다."
step "Docker Desktop → Settings → General → 'Start Docker Desktop when you sign in to your computer' 켜기 → Apply"
step "Docker Desktop → Settings → Resources 에서 CPU·메모리를 넉넉히(권장 메모리 8GB 이상 — Next 빌드 두 개가 겹칩니다)"
step "mac 터미널에서 전원 연결 중 잠자기 끄기:"
note "    sudo pmset -c sleep 0 disksleep 0 && pmset -g | grep -E ' sleep|disksleep'"
step "시스템 설정 → 사용자 및 그룹 → 자동 로그인을 이 계정으로 (재부팅 뒤에도 러너가 뜨려면 로그인 세션이 필요합니다)"
step "mac 터미널에서 확인: docker info --format '{{.Architecture}}' → aarch64, docker buildx version 이 나오면 됩니다"
pause "mac 에서 끝냈으면 Enter"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "mac: GitHub Actions 러너 설치"
RUNNER_VERSION=$(gh api repos/actions/runner/releases/latest --jq '.tag_name | ltrimstr("v")')
REG_TOKEN=$(gh api -X POST "repos/$REPO/actions/runners/registration-token" --jq .token)
say "등록 토큰은 1시간 동안만 유효합니다. mac 터미널에 아래를 그대로 붙여 넣으세요:"
printf '\n%s' "$DIM"
cat <<EOF
    mkdir -p ~/actions-runner-codemit && cd ~/actions-runner-codemit
    curl -fsSL -o runner.tar.gz https://github.com/actions/runner/releases/download/v${RUNNER_VERSION}/actions-runner-osx-arm64-${RUNNER_VERSION}.tar.gz
    tar xzf runner.tar.gz && rm runner.tar.gz
    ./config.sh --unattended --url https://github.com/${REPO} --token ${REG_TOKEN} \\
      --name mac-arm --labels mac-arm --work _work --replace
    ./svc.sh install && ./svc.sh start && ./svc.sh status
EOF
printf '%s\n' "$RESET"
note "기본 라벨 self-hosted·macOS·ARM64 는 저절로 붙고, mac-arm 을 더합니다."
note "config.sh 를 돌리는 셸에서 'which docker' 가 나와야 합니다 — 러너 서비스가 그 PATH 를 기억합니다."
pause "mac 에서 svc.sh status 가 started 로 나오면 Enter"
for _ in 1 2 3 4 5 6; do
  RUNNER_STATE=$(gh api "repos/$REPO/actions/runners" --jq '.runners[] | select(.name=="mac-arm") | "\(.status) \([.labels[].name]|join(","))"' 2>/dev/null || true)
  [[ "$RUNNER_STATE" == online* ]] && break
  note "러너가 아직 online 이 아닙니다 — 10초 뒤 다시 봅니다 (${RUNNER_STATE:-등록 안 됨})"; sleep 10
done
if [[ "$RUNNER_STATE" == online* ]]; then
  printf '  %s✓ mac-arm%s %s\n' "$GREEN" "$RESET" "$RUNNER_STATE"
else
  SKIPPED+=("mac 러너가 online 이 아님 — mac 에서 ./svc.sh status 확인"); warn "러너를 확인하지 못했습니다"
fi
pause "계속하려면 Enter"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "ghcr pull 토큰 발급"
say "staging·prod 서버가 비공개 이미지를 받을 때 쓸 읽기 전용 토큰입니다."
say "ghcr 는 SSH 키로 로그인할 수 없고, classic PAT 가 필요합니다."
open_url "https://github.com/settings/tokens/new?scopes=read:packages&description=codemit-ghcr-pull"
step "Note: codemit-ghcr-pull (미리 채워져 있음)"
step "Expiration: 원하는 기간 (만료되면 배포가 pull 에서 멈춥니다 — 달력에 적어 두세요)"
step "Select scopes: read:packages 만 체크되어 있는지 확인 → Generate token → 복사"
GHCR_USER=$(gh api user --jq .login)
note "토큰 주인: ${GHCR_USER} (sandcorporation 패키지를 읽을 수 있는 계정이어야 합니다)"
ask_secret GHCR_READ_TOKEN "토큰을 붙여 넣으세요 (ghp_...):"
[[ "$GHCR_READ_TOKEN" == ghp_* ]] || warn "classic PAT 는 보통 ghp_ 로 시작합니다 — 다시 확인하세요"
write_env GHCR_USER "$GHCR_USER"
write_env GHCR_READ_TOKEN "$GHCR_READ_TOKEN"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "pull 토큰을 두 서버 env 에 기록"
say "deploy.sh 가 배포 때마다 이 값으로 docker login 합니다."
note "oracle 의 에이전트 컨테이너는 /root/.docker 를 볼륨으로 붙이지 않아, 한 번 로그인해 두는 방식은 컨테이너를 다시 만들면 사라집니다."
if confirm "두 서버의 env 파일을 백업(.bak-ghcr-날짜)한 뒤 GHCR_USER·GHCR_READ_TOKEN 을 기록할까요?"; then
  day=$(date +%F)
  { printf 'sudo cp -p %q %q\n' "$STAGING_ENV" "$STAGING_ENV.bak-ghcr-$day"
    upsert_remote_script "$STAGING_ENV" GHCR_USER "$GHCR_USER"
    upsert_remote_script "$STAGING_ENV" GHCR_READ_TOKEN "$GHCR_READ_TOKEN"
    printf 'echo "  ✓ sub: $(sudo grep -c "^GHCR_" %q) 줄"\n' "$STAGING_ENV"
  } | on_sub
  { printf 'sudo cp -p %q %q\n' "$PROD_ENV" "$PROD_ENV.bak-ghcr-$day"
    upsert_remote_script "$PROD_ENV" GHCR_USER "$GHCR_USER"
    upsert_remote_script "$PROD_ENV" GHCR_READ_TOKEN "$GHCR_READ_TOKEN"
    printf 'echo "  ✓ oracle: $(sudo grep -c "^GHCR_" %q) 줄"\n' "$PROD_ENV"
  } | on_oracle
  say "배포 에이전트 컨테이너 안에서 로그인을 시험합니다(임시 설정 디렉터리 — 흔적을 남기지 않음):"
  login_test() {
    printf 'printf %%s %q | docker exec -i %q sh -c %q\n' "$GHCR_READ_TOKEN" "$1" \
      "d=\$(mktemp -d); r=0; DOCKER_CONFIG=\$d docker login ghcr.io -u $GHCR_USER --password-stdin >/dev/null || r=1; rm -rf \$d; [ \$r = 0 ] && echo '  ✓ $1: ghcr 로그인 성공'; exit \$r"
  }
  login_test jenkins | on_sub || SKIPPED+=("sub jenkins 컨테이너의 ghcr 로그인 시험 실패")
  login_test jenkins-desktop-agent | on_oracle || SKIPPED+=("oracle 에이전트 컨테이너의 ghcr 로그인 시험 실패")
else
  SKIPPED+=("두 서버 env 에 GHCR_USER·GHCR_READ_TOKEN 기록")
fi
pause "계속하려면 Enter"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Jenkins API 토큰 (CI 가 staging 배포를 부른다)"
say "이미지가 올라간 뒤 CI(sub 의 러너)가 Jenkins 의 staging 잡(laurio)을 부릅니다."
say "러너와 Jenkins 가 같은 호스트라 CI 는 http://127.0.0.1:8080 으로 칩니다."
ask JENKINS_UI_URL "브라우저로 여는 Jenkins 주소 (예: http://sub:8080):"
write_env JENKINS_UI_URL "$JENKINS_UI_URL"
ask JENKINS_USER "Jenkins 사용자 아이디 (빌드 권한이 있는 계정):"
write_env JENKINS_USER "$JENKINS_USER"
open_url "${JENKINS_UI_URL%/}/user/${JENKINS_USER}/security/"
note "(이 주소가 없으면 오른쪽 위 사용자 이름 → Security, 옛 버전은 → Configure 에 있습니다)"
step "API Token → Add new Token → 이름 github-actions-staging → Generate → 복사 (다시 볼 수 없습니다)"
ask_secret JENKINS_API_TOKEN "API 토큰을 붙여 넣으세요:"
write_env JENKINS_API_TOKEN "$JENKINS_API_TOKEN"
code=$(printf 'curl -s -o /dev/null -w "%%{http_code}" -u %q http://127.0.0.1:8080/job/laurio/api/json\n' \
  "${JENKINS_USER}:${JENKINS_API_TOKEN}" | on_sub || true)
if [[ "$code" == "200" ]]; then
  printf '  %s✓ sub 에서 laurio 잡 조회 200%s (빌드는 부르지 않았습니다)\n' "$GREEN" "$RESET"
  set_secret JENKINS_API_TOKEN "$JENKINS_API_TOKEN"
  set_repo_var JENKINS_USER "$JENKINS_USER"
  set_repo_var JENKINS_URL "http://127.0.0.1:8080"
else
  warn "sub 에서 조회가 ${code} 로 실패했습니다 — 아이디·토큰을 확인하고 이 위저드를 다시 돌리세요"
  SKIPPED+=("JENKINS_API_TOKEN 확인 실패(${code})")
fi
note "staging 잡의 GitHub 웹훅 트리거는 지금 끄지 않습니다 — 코드가 main 에 들어가는 그 시점에 끕니다."
pause "계속하려면 Enter"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "앱 이미지에 굳는 공개 값 → 저장소 변수"
say "세 Next 앱은 빌드할 때 NEXT_PUBLIC_* 값을 이미지에 굽습니다. CI 가 구우려면 그 값이 CI 에 있어야 합니다."
say "두 서버 env 에서 해당 줄만 읽어 STAGING_* / PROD_* 저장소 변수로 올립니다(값은 화면에 찍지 않습니다)."
read_keys='for k in PORT_ONE_V2_STORE_ID KG_INICIS_CHANNEL_KEY TOSS_SANDBOX_CLIENT_KEY TOSS_LIVE_CLIENT_KEY SENTRY_DSN_FRONTEND SENTRY_DSN_OPERATOR SENTRY_DSN_CLASSROOM CODEMIT_CONTEST_PRODUCT_ENABLED CODEMIT_PAID_CONTEST_PRODUCT_ENABLED; do sudo grep -E "^${k}=" "$F" | tail -n1; done'
STAGING_LINES=$( { printf 'F=%q\n' "$STAGING_ENV"; echo "$read_keys"; } | on_sub)
PROD_LINES=$( { printf 'F=%q\n' "$PROD_ENV"; echo "$read_keys"; } | on_oracle)
publish_env_vars() {  # PREFIX LINES TOSS_SOURCE_KEY
  local prefix="$1" lines="$2" toss_key="$3" key value
  local -A seen=()
  while IFS= read -r line; do
    [[ -z "$line" ]] && continue
    key="${line%%=*}"; value="${line#*=}"; value="${value%\"}"; value="${value#\"}"
    case "$key" in
      TOSS_SANDBOX_CLIENT_KEY|TOSS_LIVE_CLIENT_KEY) [[ "$key" == "$toss_key" ]] || continue; key=TOSS_CLIENT_KEY ;;
    esac
    seen[$key]=1
    set_repo_var "${prefix}_${key}" "$value"
  done <<< "$lines"
  # 파일에 없는 스위치는 compose 기본값과 같게 둔다(공모전 켜짐·유료 꺼짐).
  [[ -n "${seen[CODEMIT_CONTEST_PRODUCT_ENABLED]:-}" ]] || set_repo_var "${prefix}_CODEMIT_CONTEST_PRODUCT_ENABLED" true
  [[ -n "${seen[CODEMIT_PAID_CONTEST_PRODUCT_ENABLED]:-}" ]] || set_repo_var "${prefix}_CODEMIT_PAID_CONTEST_PRODUCT_ENABLED" false
  for required in PORT_ONE_V2_STORE_ID KG_INICIS_CHANNEL_KEY TOSS_CLIENT_KEY; do
    [[ -n "${seen[$required]:-}" ]] || { warn "${prefix}: ${required} 가 env 에 없습니다"; SKIPPED+=("${prefix}_${required}"); }
  done
}
if confirm "STAGING_* 와 PROD_* 저장소 변수를 올릴까요? (NEXT_PUBLIC 값이라 브라우저에 어차피 노출되는 값입니다)"; then
  publish_env_vars STAGING "$STAGING_LINES" TOSS_SANDBOX_CLIENT_KEY
  publish_env_vars PROD "$PROD_LINES" TOSS_LIVE_CLIENT_KEY
else
  SKIPPED+=("STAGING_*/PROD_* 저장소 변수")
fi
pause "마무리하려면 Enter"

finish
note "다음: 코드 작업(CI 이미지 잡·compose image 태그·deploy.sh pull·docker login)과 머지 시점의 웹훅 끄기."
note "위저드 기본값 파일: $ENV_FILE (비밀값 포함, 권한 600) — 다 끝나면 지워도 됩니다."
